import time
import threading
from collections import OrderedDict
from functools import wraps
from typing import Any, Callable, Dict, Optional, TypeVar

T = TypeVar('T')
K = TypeVar('K')

class LRUCache:
    def __init__(self, max_size: int = 128, ttl: float = 300.0):
        self.max_size = max_size
        self.ttl = ttl
        self._cache: OrderedDict[K, tuple[Any, float]] = OrderedDict()
        self._lock = threading.RLock()

    def _is_expired(self, timestamp: float) -> bool:
        return time.time() - timestamp > self.ttl

    def get(self, key: K) -> Optional[Any]:
        with self._lock:
            if key not in self._cache:
                return None
            value, timestamp = self._cache[key]
            if self._is_expired(timestamp):
                del self._cache[key]
                return None
            self._cache.move_to_end(key)
            return value

    def set(self, key: K, value: Any) -> None:
        with self._lock:
            if key in self._cache:
                del self._cache[key]
            self._cache[key] = (value, time.time())
            self._cache.move_to_end(key)
            while len(self._cache) > self.max_size:
                self._cache.popitem(last=False)

    def clear(self) -> None:
        with self._lock:
            self._cache.clear()

    def __len__(self) -> int:
        with self._lock:
            return len(self._cache)

def lru_cache(max_size: int = 128, ttl: float = 300.0):
    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        cache = LRUCache(max_size=max_size, ttl=ttl)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            cached = cache.get(key)
            if cached is not None:
                return cached
            result = func(*args, **kwargs)
            cache.set(key, result)
            return result

        wrapper.cache = cache
        return wrapper
    return decorator
